) v(code, service_no, title, division, who, classification, tx_types, fee_text, fee_php, total_minutes, total_text, confidential, doc_type_name, steps, sort_order)
join public.rms_offices o on o.code = v.code
on conflict (office_id, service_no) do update set
  title = excluded.title,
  division = excluded.division,
  who = excluded.who,
  classification = excluded.classification,
  tx_types = excluded.tx_types,
  fee_text = excluded.fee_text,
  fee_php = excluded.fee_php,
  total_minutes = excluded.total_minutes,
  total_text = excluded.total_text,
  confidential = excluded.confidential,
  doc_type_name = excluded.doc_type_name,
  steps = excluded.steps,
  sort_order = excluded.sort_order,
  updated_at = now()
where (public.rms_services.title, public.rms_services.division, public.rms_services.who, public.rms_services.classification, public.rms_services.tx_types, public.rms_services.fee_text, public.rms_services.fee_php, public.rms_services.total_minutes, public.rms_services.total_text, public.rms_services.confidential, public.rms_services.doc_type_name, public.rms_services.steps, public.rms_services.sort_order) is distinct from (excluded.title, excluded.division, excluded.who, excluded.classification, excluded.tx_types, excluded.fee_text, excluded.fee_php, excluded.total_minutes, excluded.total_text, excluded.confidential, excluded.doc_type_name, excluded.steps, excluded.sort_order);

